@Test
@Transactional
void 준영속() {
    Member m = memberRepository.save(new Member("김", 20));
    em.flush();
    em.clear();
    System.out.println("--- clear 했다, 이제 준영속 ---");
    System.out.println("영속 상태: " + em.contains(m));

    Member merged = memberRepository.save(m);
    System.out.println("같은 객체: " + (m == merged));
    System.out.println("인자 영속: " + em.contains(m));
    System.out.println("반환 영속: " + em.contains(merged));
    em.flush();
}

