    em.flush(); em.clear();

    System.out.println("--- 조회하고 이름만 바꾼다 ---");
    Member managed = memberRepository.findById(m.getId()).orElseThrow();
    managed.changeUsername("박");
    em.flush(); em.clear();

    Member after = memberRepository.findById(m.getId()).orElseThrow();
    System.out.println("이름: " + after.getUsername());
    System.out.println("나이: " + after.getAge());
    System.out.println("팀  : " + after.getTeam().getName());
}

