-- 쿼리 개수를 비교한다

@Test
@Transactional
void 개수_비교() {
    Member m = memberRepository.save(new Member("김", 20));
    em.flush(); em.clear();

    Member detached = new Member("박", 30);
    setField(detached, "id", m.getId());

    long a = counter.count(() -> {
        memberRepository.save(detached);
        em.flush();
    });
    em.clear();

    long b = counter.count(() -> {
        Member found = memberRepository.findById(m.getId()).orElseThrow();
        found.changeUsername("최");
        em.flush();
    });

    System.out.println("merge      : " + a + "개");
    System.out.println("변경 감지  : " + b + "개");
}

merge      : 2개
변경 감지  : 2개

--   개수는 같다
--   차이는 무엇을 쓰느냐다
--   merge 는 안 준 필드까지 덮는다


