-- 실무 규칙

@Service
@RequiredArgsConstructor
public class MemberService {
    private final MemberRepository memberRepository;

    @Transactional
    public Long 가입(String username, int age) {
        return memberRepository.save(new Member(username, age)).getId();
    }

    @Transactional
    public void 이름_변경(Long id, String username) {
        Member m = memberRepository.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("없음"));
        m.changeUsername(username);
        // save 를 안 부른다
    }
}

@Test
void 규칙() {
    Long id = memberService.가입("김", 20);
    memberService.이름_변경(id, "박");
}

